CREATE TABLE users ( id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'resident' CHECK (role IN ('resident','security','staff','admin')), collection_point TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE TABLE sessions ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX idx_sessions_user ON sessions(user_id); CREATE TABLE items ( id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, color TEXT NOT NULL, location TEXT NOT NULL, date TEXT NOT NULL, description TEXT NOT NULL, private_note TEXT NOT NULL, collection TEXT NOT NULL, image TEXT, illus_type TEXT, paint TEXT, accent TEXT, status TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available','collected')), sample INTEGER NOT NULL DEFAULT 0, reported_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX idx_items_status ON items(status, collection); CREATE TABLE claims ( id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES items(id), user_id TEXT NOT NULL REFERENCES users(id), claimant_name TEXT NOT NULL, proof TEXT NOT NULL, last_seen TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','collected')), pickup_code TEXT, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, handed_by TEXT REFERENCES users(id), handed_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX idx_claims_user ON claims(user_id); CREATE INDEX idx_claims_item ON claims(item_id); CREATE TABLE audit_log ( id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL DEFAULT (datetime('now')), user_id TEXT, action TEXT NOT NULL, target TEXT, detail TEXT ); CREATE INDEX idx_audit_action ON audit_log(action, target, at);
